using System;
using System.IO;
using System.Windows;
using System.Windows.Threading;

namespace PZWorkshopDownloader;

public partial class App : Application
{
    private static readonly string LogPath = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader", "crash.log");

    protected override void OnStartup(StartupEventArgs e)
    {
        base.OnStartup(e);

        DispatcherUnhandledException += (_, args) =>
        {
            LogAndShow(args.Exception, "UI thread");
            args.Handled = true; // keep the app alive so you can see the message
        };

        AppDomain.CurrentDomain.UnhandledException += (_, args) =>
        {
            LogAndShow(args.ExceptionObject as Exception, "background thread (fatal)");
        };

        System.Threading.Tasks.TaskScheduler.UnobservedTaskException += (_, args) =>
        {
            LogAndShow(args.Exception, "async task");
            args.SetObserved();
        };
    }

    private static void LogAndShow(Exception? ex, string where)
    {
        var text = $"[{DateTime.Now}] Unhandled exception on {where}:\n{ex}\n\n";
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(LogPath)!);
            File.AppendAllText(LogPath, text);
        }
        catch
        {
            // If we can't even write the log, fall through to the message box anyway.
        }

        MessageBox.Show(
            $"An unexpected error occurred on the {where}:\n\n{ex?.Message}\n\n" +
            $"Full details were saved to:\n{LogPath}",
            "PZ Workshop Downloader — Error",
            MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

