{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";

    private string _status = "Queued";
    public string Status
    {
        get => _status;
        set { _status = value; OnPropertyChanged(); }
    }

    // Latest SteamCMD output line, or a short result summary once finished.
    private string _detail = "";
    public string Detail
    {
        get => _detail;
        set { _detail = value; OnPropertyChanged(); }
    }

    private string _startedAt = "";
    public string StartedAt
    {
        get => _startedAt;
        set { _startedAt = value; OnPropertyChanged(); }
    }

    private string _finishedAt = "";
    public string FinishedAt
    {
        get => _finishedAt;
        set { _finishedAt = value; OnPropertyChanged(); }
    }

