using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

namespace PZWorkshopDownloader.Services;

public static class SteamCmdService
{
    public const string AppId = "108600"; // Project Zomboid

    private static readonly string AppDir = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader");

    private static readonly string SteamCmdDir = Path.Combine(AppDir, "steamcmd");
    private static readonly string SteamCmdExe = Path.Combine(SteamCmdDir, "steamcmd.exe");
    private const string SteamCmdZipUrl = "https://steamcdn-a.akamaihd.net/client/installer/steamcmd.zip";

    private static bool _bootstrapped = false;
    private static readonly SemaphoreSlim RunLock = new(1, 1);

    public static string GetContentPath(string workshopId) =>
        Path.Combine(SteamCmdDir, "steamapps", "workshop", "content", AppId, workshopId);

    public static async Task EnsureSteamCmdAsync(Action<string> log)
    {
        if (File.Exists(SteamCmdExe)) return;

        log("SteamCMD not found — downloading it (one-time setup, ~5 MB)...");
        Directory.CreateDirectory(SteamCmdDir);

        using var http = new HttpClient();
        var data = await http.GetByteArrayAsync(SteamCmdZipUrl);
        var zipPath = Path.Combine(SteamCmdDir, "steamcmd.zip");
        await File.WriteAllBytesAsync(zipPath, data);
        ZipFile.ExtractToDirectory(zipPath, SteamCmdDir, overwriteFiles: true);
        File.Delete(zipPath);

        if (!File.Exists(SteamCmdExe))
            throw new Exception("SteamCMD download finished but steamcmd.exe was not found.");

        log("SteamCMD ready.");
    }

    private static async Task<int> RunSteamCmdAsync(IEnumerable<string> args, Action<string> log)
    {
        var psi = new ProcessStartInfo
        {
            FileName = SteamCmdExe,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
            WorkingDirectory = SteamCmdDir,
        };
        foreach (var a in args) psi.ArgumentList.Add(a);

        using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };
        process.OutputDataReceived += (_, e) => { if (e.Data != null) log(e.Data); };
        process.ErrorDataReceived += (_, e) => { if (e.Data != null) log(e.Data); };

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();
        await process.WaitForExitAsync();
        return process.ExitCode;
    }

    /// <summary>
    /// SteamCMD self-updates on first run (and sometimes relaunches itself
    /// to do so, which can return a nonzero exit code even though
    /// everything worked). Running a harmless '+quit' once up front absorbs
    /// that self-update so it doesn't interleave with a real download later.
    /// </summary>
    private static async Task BootstrapAsync(Action<string> log)
    {
        if (_bootstrapped) return;
        log("Preparing SteamCMD (first-time update check)...");
        await RunSteamCmdAsync(new[] { "+quit" }, log);
        _bootstrapped = true;
    }

    /// <summary>
    /// Downloads workshopId via SteamCMD, then installs it into destFolder
    /// using the layout Project Zomboid actually expects for local mods:
    /// destFolder/&lt;workshopId&gt; &lt;ModFolderName&gt;/&lt;mod files directly&gt;
    /// (not the raw Steam cache layout, which nests content under
    /// content/&lt;id&gt;/mods/&lt;ModFolderName&gt;/).
    ///
    /// A single workshop item can contain more than one mod folder (some
    /// "collection" style items do), so this can install more than one
    /// destination folder per item. Returns every folder that was created.
    /// </summary>
    public static async Task<List<string>> DownloadModAsync(string workshopId, string destFolder, Action<string> log)
    {
        // Serialize downloads -- SteamCMD does not support concurrent instances well.
        await RunLock.WaitAsync();
        try
        {
            await EnsureSteamCmdAsync(log);
            await BootstrapAsync(log);

            log($"Downloading workshop item {workshopId} via SteamCMD...");
            var args = new[]
            {
                "+force_install_dir", SteamCmdDir,
                "+login", "anonymous",
                "+workshop_download_item", AppId, workshopId,
                "+quit",
            };
            int exitCode = await RunSteamCmdAsync(args, log);

            var downloadedPath = GetContentPath(workshopId);
            bool hasFiles = Directory.Exists(downloadedPath) &&
                            Directory.EnumerateFileSystemEntries(downloadedPath).Any();

            if (!hasFiles)
            {
                throw new Exception(
                    $"SteamCMD did not produce any files for item {workshopId} " +
                    $"(exit code {exitCode}). The item may be invalid, removed, or restricted.");
            }

            if (exitCode != 0)
            {
                // SteamCMD sometimes self-updates again right after a
                // successful download and returns a nonzero code from that
                // unrelated relaunch. Since the files are present, treat
                // this as benign.
                log($"Note: SteamCMD returned exit code {exitCode}, but the mod files " +
                    $"were found on disk — continuing.");
            }

            var installedPaths = new List<string>();
            var modsSubdir = Path.Combine(downloadedPath, "mods");

            if (Directory.Exists(modsSubdir) && Directory.GetDirectories(modsSubdir).Length > 0)
            {
                // Normal case: PZ workshop items ship their actual mod
                // folder(s) under a "mods" subfolder.
                foreach (var modDir in Directory.GetDirectories(modsSubdir))
                {
                    var rawFolderName = Path.GetFileName(modDir);
                    // Prefer mod.info's "name=" (the human-readable display
                    // name) over the raw subfolder name -- mod authors very
                    // commonly name that physical folder after their internal
                    // "id=" instead, which produces cryptic, non-descriptive
                    // installed folder names otherwise.
                    var modFolderName = GetModDisplayName(modDir) ?? rawFolderName;
                    var dest = Path.Combine(destFolder, $"{workshopId} {modFolderName}");
                    if (Directory.Exists(dest)) Directory.Delete(dest, recursive: true);
                    CopyDirectory(modDir, dest);
                    installedPaths.Add(dest);
                    log($"Installed mod to {dest}");
                }
            }
            else
            {
                // Fallback for oddly-structured items with no "mods" folder --
                // install the whole downloaded item as-is.
                var dest = Path.Combine(destFolder, workshopId);
                if (Directory.Exists(dest)) Directory.Delete(dest, recursive: true);
                CopyDirectory(downloadedPath, dest);
                installedPaths.Add(dest);
                log($"Note: no 'mods' subfolder found in this item; installed raw content to {dest}");
            }

            return installedPaths;
        }
        finally
        {
            RunLock.Release();
        }
    }

    /// <summary>
    /// Reads mod.info inside a mod folder and returns its "name=" value
    /// (sanitized for use as a filesystem folder name), or null if there's
    /// no mod.info or no name field.
    /// </summary>
    private static string? GetModDisplayName(string modDir)
    {
        try
        {
            var infoPath = Path.Combine(modDir, "mod.info");
            if (!File.Exists(infoPath)) return null;

            foreach (var line in File.ReadAllLines(infoPath))
            {
                var m = Regex.Match(line.Trim(), @"^name\s*=\s*(.+)$", RegexOptions.IgnoreCase);
                if (m.Success)
                {
                    var name = m.Groups[1].Value.Trim();
                    if (!string.IsNullOrWhiteSpace(name))
                        return SanitizeFileName(name);
                }
            }
        }
        catch
        {
            // Unreadable mod.info -- fall back to the raw folder name.
        }
        return null;
    }

    /// <summary>
    /// Reads mod.info inside a mod folder and returns every value declared in
    /// its require= entries. Values are either a numeric workshop id or an
    /// internal mod identifier (often backslash-prefixed, e.g. "\NeatUI_Framework");
    /// the backslash prefix and any comma/semicolon separation are stripped.
    /// Returns an empty list when there is no readable mod.info / no require field.
    /// </summary>
    public static List<string> GetRequiresFields(string modDir)
    {
        var requires = new List<string>();
        try
        {
            var infoPath = Path.Combine(modDir, "mod.info");
            if (!File.Exists(infoPath)) return requires;

            foreach (var line in File.ReadAllLines(infoPath))
            {
                var m = Regex.Match(line.Trim(), @"^require\s*=\s*(.+)$", RegexOptions.IgnoreCase);
                if (!m.Success) continue;

                var value = m.Groups[1].Value.Trim();
                if (string.IsNullOrWhiteSpace(value)) continue;

                foreach (var part in value.Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    var id = part.Trim();
                    if (id.StartsWith("\\")) id = id[1..].Trim();
                    if (id.Length > 0) requires.Add(id);
                }
            }
        }
        catch
        {
            // Unreadable mod.info -- no dependencies can be declared.
        }
        return requires;
    }

    /// <summary>
    /// Reads mod.info inside a mod folder and returns its declared identifier
    /// values (the letter-based "id=" and the human-readable "name="). These are
    /// used ONLY to resolve a require= reference (e.g. "\NeatUI_Framework") to the
    /// real workshop id of an installed mod -- never to identify a mod on its own.
    /// </summary>
    public static List<string> GetModIdentifiers(string modDir)
    {
        var ids = new List<string>();
        try
        {
            var infoPath = Path.Combine(modDir, "mod.info");
            if (!File.Exists(infoPath)) return ids;

            foreach (var line in File.ReadAllLines(infoPath))
            {
                var m = Regex.Match(line.Trim(), @"^(id|name)\s*=\s*(.+)$", RegexOptions.IgnoreCase);
                if (m.Success && !string.IsNullOrWhiteSpace(m.Groups[2].Value))
                    ids.Add(m.Groups[2].Value.Trim());
            }
        }
        catch
        {
            // Unreadable mod.info -- no identifiers to match against.
        }
        return ids;
    }

    private static string SanitizeFileName(string name)
    {
        foreach (var c in Path.GetInvalidFileNameChars())
            name = name.Replace(c, '_');
        return name;
    }

    private static void CopyDirectory(string sourceDir, string destDir)
    {
        Directory.CreateDirectory(destDir);
        foreach (var file in Directory.GetFiles(sourceDir))
            File.Copy(file, Path.Combine(destDir, Path.GetFileName(file)), overwrite: true);
        foreach (var dir in Directory.GetDirectories(sourceDir))
            CopyDirectory(dir, Path.Combine(destDir, Path.GetFileName(dir)));
    }
}

