using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

namespace PZWorkshopDownloader.Services;

public class WorkshopItemDetails
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
    public long FileSize { get; set; }
    public DateTimeOffset TimeCreated { get; set; }
    public DateTimeOffset TimeUpdated { get; set; }

    /// <summary>
    /// Steam's "hcontent_file" value -- a manifest id that changes every time
    /// the item's actual file content changes. This is a much better proxy
    /// for "version" than time_updated, which can shift for reasons that
    /// don't affect the files (title edits, description edits, etc.).
    /// </summary>
    public string ContentManifestId { get; set; } = "";

    /// <summary>Author's SteamID64. Steam's public API doesn't expose a
    /// friendly display name without an API key, so this is the raw ID.</summary>
    public string Creator { get; set; } = "";
}

public static class WorkshopApiService
{
    private static readonly HttpClient Http = new();

    /// <summary>
    /// Uses Steam's public, key-less GetPublishedFileDetails endpoint.
    /// Throws if the item id is invalid, private, or removed.
    /// </summary>
    public static async Task<WorkshopItemDetails> GetDetailsAsync(string workshopId)
    {
        var content = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["itemcount"] = "1",
            ["publishedfileids[0]"] = workshopId,
        });

        var resp = await Http.PostAsync(
            "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/", content);
        resp.EnsureSuccessStatusCode();

        var json = await resp.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var list = doc.RootElement.GetProperty("response").GetProperty("publishedfiledetails");
        if (list.GetArrayLength() == 0)
            throw new Exception($"No workshop item found for id {workshopId}");

        var details = list[0];
        if (!details.TryGetProperty("result", out var result) || result.GetInt32() != 1)
            throw new Exception($"Workshop item {workshopId} not found or is private/removed");

        return new WorkshopItemDetails
        {
            Id = workshopId,
            Title = GetString(details, "title") ?? $"Workshop item {workshopId}",
            FileSize = GetLong(details, "file_size"),
            TimeCreated = GetUnixTime(details, "time_created"),
            TimeUpdated = GetUnixTime(details, "time_updated"),
            ContentManifestId = GetString(details, "hcontent_file") ?? "",
            Creator = GetString(details, "creator") ?? "",
        };
    }

    // Steam's API sometimes returns numeric fields as JSON strings, so
    // these helpers accept either representation.

    private static string? GetString(JsonElement el, string prop) =>
        el.TryGetProperty(prop, out var v) && v.ValueKind != JsonValueKind.Null ? v.ToString() : null;

    private static long GetLong(JsonElement el, string prop)
    {
        if (!el.TryGetProperty(prop, out var v)) return 0;
        return v.ValueKind switch
        {
            JsonValueKind.Number => v.GetInt64(),
            JsonValueKind.String when long.TryParse(v.GetString(), out var parsed) => parsed,
            _ => 0,
        };
    }

    private static DateTimeOffset GetUnixTime(JsonElement el, string prop)
    {
        var seconds = GetLong(el, prop);
        return seconds > 0 ? DateTimeOffset.FromUnixTimeSeconds(seconds) : default;
    }
}

