    private static long GetDirectorySize(string path)
    {
        long total = 0;
        try
        {
            foreach (var f in Directory.EnumerateFiles(path, "*", SearchOption.AllDirectories))
                total += new FileInfo(f).Length;
        }
        catch { /* ignore inaccessible files */ }
        return total;
