    private async void UpdateAllButton_Click(object sender, RoutedEventArgs e)
    {
        var toUpdate = _downloadedMods.Where(m => m.NeedsUpdate).ToList();
        if (toUpdate.Count == 0)
        {
            MessageBox.Show("No updates available. Try 'Refresh Mod List' first.");
            return;
        }

        AppendLog($"Updating all: {toUpdate.Count} mod(s)...");
        foreach (var mod in toUpdate)
        {
            if (_settings.BackupUpdatedMods) BackupMod(mod.Folder);
            RemoveOldModFolder(mod.Folder);
            await StartDownloadAsync(mod.Id, mod.ModName, showFolderWarning: false);
        }

        await RefreshDownloadedModsAsync();
    }

    /// <summary>
    /// Deletes the folder currently on disk for a mod before an update
    /// redownloads it. This matters because SteamCMD's fresh download can
    /// name the mod's folder slightly differently than what's already
    /// installed (renamed subfolder, capitalization change, etc.) -- the
    /// installer only overwrites a folder when the name matches exactly,
    /// so without this step a mismatch leaves the old copy behind and
    /// creates a duplicate instead of replacing it.
    /// </summary>
    private void RemoveOldModFolder(string folderName)
    {
        try
        {
            var path = Path.Combine(_settings.ModsFolder, folderName);
            if (Directory.Exists(path)) Directory.Delete(path, recursive: true);
        }
        catch (Exception ex)
        {
            // Best-effort -- if this fails, the download will still overwrite
            // any folder whose name happens to match exactly.
            AppendLog($"Could not remove old folder \"{folderName}\" before redownload: {ex.Message}", "WARNING");
        }
    }

    private void BackupMod(string folderName)
    {
        try
        {
            var src = Path.Combine(_settings.ModsFolder, folderName);
            if (!Directory.Exists(src)) return;
            var backupDir = Path.Combine(_settings.ModsFolder, "_backups", folderName, DateTime.Now.ToString("yyyyMMdd_HHmmss"));
            Directory.CreateDirectory(Path.GetDirectoryName(backupDir)!);
            CopyDirectory(src, backupDir);
        }
        catch
        {
            // Best-effort backup; don't block the update if it fails.
        }
    }

    private static void CopyDirectory(string sourceDir, string destDir)
    {
        Directory.CreateDirectory(destDir);
        foreach (var file in Directory.GetFiles(sourceDir))
            File.Copy(file, Path.Combine(destDir, Path.GetFileName(file)), overwrite: true);
        foreach (var dir in Directory.GetDirectories(sourceDir))
            CopyDirectory(dir, Path.Combine(destDir, Path.GetFileName(dir)));
    }

